class AgoFormatter {
  constructor(locale) {
    this.locale = locale
    this.relativeTimeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "always", style: "long" })
  }

  format(dt) {
    const now = new Date()
    const seconds = (now - dt) / 1000
    const minutes = seconds / 60
    const hours = minutes / 60
    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (years >= 1) return this.#formatUnit("year", years)
    if (months >= 1) return this.#formatUnit("month", months)
    if (weeks >= 1) return this.#formatUnit("week", weeks)
    if (days >= 1) return this.#formatUnit("day", days)
    if (hours >= 1) return this.#formatUnit("hour", hours)
    if (minutes >= 1) return this.#formatUnit("minute", minutes)

    return translate("less_than_a_minute_ago")
  }

  #formatUnit(unit, quantity) {
    return this.relativeTimeFormatter.format(-Math.floor(quantity), unit)
  }
}

class DaysAgoFormatter {
  constructor(locale) {
    this.locale = locale
    this.relativeTimeFormatter = new Intl.RelativeTimeFormat(locale, { numeric: "auto" })
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) return styleableValue(this.relativeTimeFormatter.format(-days, "day"))
    return `${styleableValue(this.relativeTimeFormatter.format(-days, "day"))}`
  }
}

class DaysAgoOrWeekdayFormatter {
  constructor(locale) {
    this.locale = locale
  }

  format(date) {
    const days = differenceInDays(date, new Date())

    if (days <= 1) {
      return new DaysAgoFormatter(this.locale).format(date)
    } else {
      return new Intl.DateTimeFormat(this.locale, { weekday: "long", month: "long", day: "numeric" }).format(date)
    }
  }
}

